sap.ui.define([
  "sap/ui/model/Filter",
  "sap/ui/model/FilterOperator"
], function (Filter, FilterOperator) {
  "use strict";
  return {
    onBeforeRebindTableExtension: function (event) {
      const bindingParams = event.getParameter("bindingParams");
      const priority = this.byId("priorityFilter").getSelectedKey();
      if (priority) {
        bindingParams.filters.push(new Filter("Priority", FilterOperator.EQ, priority));
      }
    },
    getCustomAppStateDataExtension: function (customData) {
      customData.priority = this.byId("priorityFilter").getSelectedKey();
    },
    restoreCustomAppStateDataExtension: function (customData) {
      this.byId("priorityFilter").setSelectedKey(customData.priority || "");
    }
  };
});

sap.ui.define([], function () {
  "use strict";
  return {
    // controller extension of sap.suite.ui.generic.template.ListReport.view.ListReport
    // beforeDeleteProperties contains information about the items selected for deletion
    beforeDeleteExtension: function (beforeDeleteProperties) {
      return {
        title: "Delete Sales Orders",
        text: "Delete the selected sales orders? Their deliveries will also be cancelled.",
        unsavedChanges: "Some of these orders have unsaved changes by other users.",
        undeletableText: "Some of the selected orders cannot be deleted."
      };
    }
  };
});
